// The main button style: Generated by Claude Opus 5.5
import React from 'react';
import { Pressable, Text, View } from 'react-native';
import { ArrowRightIcon } from './icons';
import { HardShadow } from './decor';
import { Theme, fonts, spacing } from '../constants/theme';

type Props = {
  label: string;
  onPress: () => void;
  theme: Theme;
  disabled?: boolean;
  loading?: boolean;
};

export function ArrowButton({ label, onPress, theme, disabled = false, loading = false }: Props) {
  const inactive = disabled || loading;
  const button = (
    <Pressable
      onPress={onPress}
      disabled={inactive}
      accessibilityRole="button"
      accessibilityLabel={label}
      accessibilityState={{ disabled: inactive, busy: loading }}
      style={({ pressed }) => ({
        minHeight: spacing.buttonHeight,
        flexDirection: 'row',
        backgroundColor: inactive ? theme.disabled : theme.primary,
        borderWidth: theme.borderWidth,
        borderColor: theme.ink,
        // pressing "pushes" the button into its shadow
        transform: pressed && !inactive ? [{ translateX: 3 }, { translateY: 3 }] : [],
      })}
    >
      <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>
        <Text
          style={{
            fontFamily: fonts.label,
            fontSize: 20,
            letterSpacing: 1.2,
            textTransform: 'uppercase',
            color: inactive ? theme.ink : theme.onPrimary,
          }}
        >
          {loading ? 'One sec…' : label}
        </Text>
      </View>
      <View
        style={{
          width: spacing.arrowBlock,
          alignItems: 'center',
          justifyContent: 'center',
          backgroundColor: theme.arrowBg,
          borderLeftWidth: theme.borderWidth,
          borderLeftColor: theme.ink,
        }}
      >
        <ArrowRightIcon color={theme.arrowFg} />
      </View>
    </Pressable>
  );

  // Disabled buttons sit flat (transparent shadow), like in the mockups,
  // but keep the same spacing so nothing jumps when the button enables.
  return (
    <HardShadow offset={spacing.shadow} color={inactive ? 'transparent' : theme.ink}>
      {button}
    </HardShadow>
  );
}
